li sum[N], df[N], res[N];

inline void add(int lf, int rg, int k, int b) {
	if(lf > rg)
		return;

	sum[lf] += b;
	df[lf] += k;

	sum[rg + 1] -= b + k * 1ll * (rg - lf);
	df[rg] -= k;
}

inline void calc() {
	li curdf = 0;
	forn(i, n) {
		sum[i] += curdf;
		curdf += df[i];
	}

	li cursm = 0;
	forn(i, n) {	
		cursm += sum[i];
		res[i] += cursm;
	}
}

inline void solve() {
	memset(sum, 0, sizeof sum);
	memset(df, 0, sizeof df);
	memset(res, 0, sizeof res);

	forn(i, n) {
		int c1 = i + 1, p1 = 0;
		int c2 = n,     p2 = p1 + c2 - c1;
		int c3 = i,     p3 = p2 + c3;

		if(p[i] <= c3) {
			add(p1, p2, 1, c1 - p[i]);
			add(p2 + 1, p2 + p[i], -1, p[i] - 1);
			add(p2 + p[i] + 1, p3, 1, 1);
		} else {
			add(p1, p1 + p[i] - c1, -1, p[i] - c1);
			add(p1 + p[i] - c1 + 1, p2, 1, 1);
			add(p2 + 1, p3, -1, p[i] - 1);
		}
	}

