inline void precalc() {
	memset(ls, -1, sizeof ls);

	ls[0] = ls[1] = 1;
	fore(i, 2, N) {
		if(ls[i] != -1)
			continue;

		ls[i] = i;
		for(li j = i * 1ll * i; j < N; j += i)
			if(ls[j] == -1)
				ls[j] = i;
	}
}

inline vector<pt> fact(int n[3]) {
	vector<int> divs;

	forn(i, 3) {
		int cur = n[i];
		while(ls[cur] != cur) {
			divs.pb(ls[cur]);
			cur /= ls[cur];
		}
		if(cur > 1)
			divs.pb(cur);
	}

	sort(all(divs));
	vector<pt> ans;

	int u = 0;
	while(u < sz(divs)) {
		int v = u;
		while(v < sz(divs) && divs[v] == divs[u])
			v++;

		ans.pb(mp(divs[u], v - u));
		u = v;
	}

	return ans;
}

