int gcd(int a, int b) {
	if(a == 0)
		return b;
	return gcd(b % a, a);
}

int exgcd(int a, li &x, int b, li &y) {
	if(a == 0) {
		x = 0, y = 1;
		return b;
	}

	li xx, yy;
	int g = exgcd(b % a, xx, a, yy);

	x = yy - b / a * xx;
	y = xx;

	return g;
}

const int N = 200 * 1000 + 555;
int t, n, a[N];

inline bool read() {
	if(!(cin >> t >> n))
	    return false;
	forn(i, n)
		assert(scanf("%d", &a[i]) == 1);
	return true;
}

int pf[N], s;

inline li up(li a, li b) {
	return (a + b - 1) / b;
}

inline int findPos(int a, int b, int c) {
	li x, y;
	int g = exgcd(a, x, b, y);
	assert(c % g == 0);

	x *= +c / g;
	y *= -c / g;
	assert(a * 1ll * x - b * 1ll * y == c);

	int ag = a / g;
	int bg = b / g;

	li k = 0;
	if(x < 0)
		k = up(-x, bg);
	if(x >= bg)
		k = -up(x - bg, bg);	
	x += bg * k;
	y += ag * k;

	assert(0 <= x && x < bg);

	k = 0;
	if(y < 0)
		k = up(-y, ag);
	x += bg * k;
	y += ag * k;

	return x;
}

map< int, set<pt> > cycle;

int ans[N];

inline void solve() {
	cycle.clear();
	pf[0] = 0;
	fore(i, 1, n)
		pf[i] = (pf[i - 1] + a[i]) % t;

	s = (a[0] + pf[n - 1]) % t;
	int g = gcd(s, t);

	forn(i, n) {
		int st = pf[i] % g;
		auto& cc = cycle[st];

		int pos = findPos(s, t, pf[i] - st);

		if(cc.empty()) {
			ans[i] += t / g;
			cc.insert(pt(pos, -i));
		} else {
			auto rg = cc.lower_bound(pt(pos, -i));
			if(rg == cc.end()) {
				ans[i] += t / g - pos;
				rg = cc.begin();
				ans[i] += rg->x;
			} else
				ans[i] += rg->x - pos;

			auto lf = cc.lower_bound(pt(pos, -i));
			if(lf == cc.begin())
				lf = --cc.end();
			else
				lf--;
			ans[ -(lf->y) ] -= ans[i];

			cc.insert(pt(pos, -i));
		} 
	}

	forn(i, n)
		printf("%d ", ans[i]);
	puts("");
}

